import { CERTIFICATES, STYLES } from "../utils/types";
import { PlainDate, YearMonthDay } from "./date";

/**
 * Bad spreadsheet data is meant to fail loudly rather than be papered over, but a bare
 * `Unkown Date Format: ` or `Cannot read properties of undefined` says nothing about which row
 * to go and fix. These wrap a failure in the identity of the row that caused it.
 */

/** The spreadsheet row a header-stripped record came from, for quoting in an error. */
export const sheetRow = (index: number) => index + 2;

/**
 * Runs `parse`, re-throwing any failure prefixed with what was being read.
 *
 * The original error is kept as `cause`, so the underlying message and stack survive.
 */
export const describing = <T>(context: string, parse: () => T): T => {
  try {
    return parse();
  } catch (cause) {
    const detail = cause instanceof Error ? cause.message : String(cause);
    throw new Error(`${context}: ${detail}`, { cause });
  }
};

/** Throws with `context` prefixed, for a problem detected rather than caught. */
export const sheetError = (context: string, detail: string): never => {
  throw new Error(`${context}: ${detail}`);
};

/**
 * A reader over a closed vocabulary, naming the row a bad cell came from.
 *
 * Every sheet has columns the model types as a union and the sheet types as free text. Cast
 * straight across, a bad cell surfaces a long way from the row that carried it: a colour lookup
 * answering `undefined` mid-render, or — worse, because nothing looks wrong — a filter quietly
 * keeping a row it was meant to hide. Read through here, the row names itself.
 *
 * Matched on the folded value and answered with the vocabulary's own spelling, these columns being
 * hand-typed behind a dropdown that only suggests: `Anime`, `anime ` and `anime` are one answer,
 * and the one the model holds is the one the table declares.
 */
export const readChecked = <T extends string>(values: readonly T[], noun: string) => {
  const spelling = new Map(values.map((value) => [value.toLowerCase(), value]));
  return (value = "", where: string): T =>
    spelling.get(value.trim().toLowerCase()) ?? sheetError(where, `"${value}" is not ${noun}`);
};

/**
 * Reads a certificate cell, rejecting one the colour map could not paint.
 *
 * The Games, Shows and Movies sheets record a certificate and feed it to `certificateToColour`,
 * which throws on a value it does not know. Left to reach that, the failure surfaces from inside a
 * render and names the value but not the row carrying it.
 */
export const readCertificate = readChecked(CERTIFICATES, "a certificate");

/**
 * Reads a Style cell against the vocabulary Games, Shows and Movies share.
 *
 * Guest mode hides anime on Shows and Movies, so a cell that fails to say so puts a hidden item on
 * screen rather than a wrong figure. One reader for the three sheets, so a word one of them accepts
 * is a word all of them accept.
 */
export const readStyle = readChecked(STYLES, "a style");

/**
 * Reads a genre cell, rejecting one nobody filled in.
 *
 * The vocabulary is open-ended — the shared ramp answers `NEUTRAL_FILL` off its table — so the only
 * thing checkable here is that a value is there at all. That is worth checking on its own: an empty
 * cell reaches every genre surface as a group with no name, drawing the same neutral an unrecognised
 * genre draws, so a row nobody finished is indistinguishable from a genre nobody has coloured yet.
 *
 * The default is what covers a row the sheet truncated: the API ends a row at its last filled cell,
 * so a half-entered row carries no `Genre` key at all rather than an empty one.
 */
export const readGenre = (value = "", where: string): string => value || sheetError(where, "no genre recorded");

/**
 * Reads a date cell that has to carry a day, answering the `YearMonthDay` its model claims.
 *
 * The check is what earns the type rather than a cast asserting it: `PlainDate.from` answers a
 * `Year` for a four-character cell, and asserting that to be a `YearMonthDay` is a claim the
 * compiler then trusts everywhere downstream. What it reaches is a chart placing the value on a
 * day scale — where a bare year either compares as a shorter string and drops the row without a
 * word, or arrives as an offset of `NaN` naming no row at all. Rejected here, it names its own.
 */
export const readFullDate = (value = "", where: string): YearMonthDay => {
  const parsed = describing(where, () => PlainDate.from(value));
  return parsed instanceof YearMonthDay ? parsed : sheetError(where, `"${value}" is a bare year, not a full date`);
};
